fn insert_source_snapshot(items: &mut BTreeMap<String, ContractRecord>) {
    let fields = [
        ("schema", "literal"),
        ("requirement_id", "string"),
        ("source_id", "string"),
        ("captured_at", "string"),
        ("source", "object"),
        ("content", "object"),
    ];
    let order: Vec<_> = fields.iter().map(|(name, _)| *name).collect();
    let description = json!({
        "schema": "work-contract-description",
        "id": "work-source-snapshot",
        "kind": "artifact",
        "caller_constructible": false,
        "required": order,
        "optional": [],
        "canonical_order": order,
        "fields": fields.iter().map(|(name, field_type)| json!({
            "name": name, "type": field_type, "required": true,
            "reference": null, "constraints": if *name == "source" {
                json!({"variants": {
                    "github_issue": {"required": ["kind", "repository", "number", "url"]},
                    "file": {"required": ["kind", "path", "media_type"],
                        "media_type": {"format": "RFC 6838 type/subtype without parameters",
                            "host_provided": true, "preserve_exact_value": true},
                        "example": {"kind":"file", "path":"原始需求.pdf", "media_type":"application/pdf"}},
                    "user_text": {"required": ["kind"]}
                }})
            } else { json!({}) }
        })).collect::<Vec<_>>(),
        "example": {
            "schema": "work-source-snapshot",
            "requirement_id": "example",
            "source_id": "SRC-001",
            "captured_at": "2026-10-03T00:00:00Z",
            "source": {"kind": "user_text"},
            "content": {"path": "source.txt", "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "size": 0}
        }
    });
    let record = json!({
        "description": description,
        "scaffold_error": {
            "reason_code": "contract_scaffold_requires_request",
            "message": "Only semantic request contracts have public input scaffolds.",
            "details": {"contract_id": "work-source-snapshot", "kind": "artifact"}
        }
    });
    items.insert(
        "work-source-snapshot".into(),
        serde_json::from_value(record).expect("valid Source Snapshot contract"),
    );
}

fn insert_discussion_trace_fields(items: &mut BTreeMap<String, ContractRecord>) {
    for id in ["work-task-index", "work-task-collection-projection"] {
        let record = items.get_mut(id).expect("formal contract exists");
        record.description.optional.push("discussion".into());
        let position = record
            .description
            .canonical_order
            .iter()
            .position(|name| name == "instruction_selection")
            .expect("instruction field");
        record
            .description
            .canonical_order
            .insert(position + 1, "discussion".into());
        record.description.fields.insert(
            position + 1,
            crate::contract::ContractField {
                name: "discussion".into(),
                field_type: "object".into(),
                required: false,
                reference: crate::common::Nullable::Null,
                constraints: BTreeMap::from([
                    (
                        "required".into(),
                        json!([
                            "session_path",
                            "revision",
                            "content_sha256",
                            "decision_versions",
                            "task_decisions"
                        ]),
                    ),
                    ("additional_properties".into(), json!(false)),
                    (
                        "session_path".into(),
                        json!("outputs/work/discussions/<requirement-id>/session.json"),
                    ),
                    ("revision_minimum".into(), json!(1)),
                    (
                        "content_sha256".into(),
                        json!("64 lowercase hexadecimal characters"),
                    ),
                    (
                        "decision_versions".into(),
                        json!("D IDs map to positive question versions"),
                    ),
                    (
                        "task_decisions".into(),
                        json!("Every formal TASK maps to unique IDs in decision_versions"),
                    ),
                ]),
            },
        );
    }
}

fn insert_source_responses(items: &mut BTreeMap<String, ContractRecord>) {
    let manifest = items["work-source-snapshot"].description.example.clone();
    for (id, fields, example) in [
        (
            "work-source-read",
            vec![
                ("schema", "literal", None),
                ("manifest", "object", Some("work-source-snapshot")),
                ("bytes", "array<integer>", None),
            ],
            json!({"schema":"work-source-read", "manifest":manifest, "bytes":[]}),
        ),
        (
            "work-source-validation",
            vec![
                ("schema", "literal", None),
                ("status", "literal", None),
                ("requirement_id", "string", None),
                ("source_id", "string", None),
                ("content_sha256", "string", None),
                ("content_size", "integer", None),
            ],
            json!({"schema":"work-source-validation", "status":"valid", "requirement_id":"example",
                "source_id":"SRC-001", "content_sha256":manifest["content"]["sha256"], "content_size":0}),
        ),
    ] {
        let order: Vec<_> = fields.iter().map(|(name, _, _)| *name).collect();
        let record = json!({"description": {
            "schema":"work-contract-description", "id":id, "kind":"response", "caller_constructible":false,
            "required":order, "optional":[], "canonical_order":order,
            "fields":fields.iter().map(|(name, field_type, reference)| json!({
                "name":name, "type":field_type, "required":true, "reference":reference, "constraints":{}
            })).collect::<Vec<_>>(), "example":example
        }, "scaffold_error": {"reason_code":"contract_scaffold_requires_request",
            "message":"Only semantic request contracts have public input scaffolds.", "details":{"contract_id":id,"kind":"response"}}});
        items.insert(
            id.into(),
            serde_json::from_value(record).expect("valid Source response contract"),
        );
    }
}

